// Identity is one Copy of the packed body. The public struct is not the
// wire, so dest is the record image and scatter lands the value.
var FixedTableFixedPlan = tableFixedPlan{Entries: []TableFixedEntry{{
	Src: 0, Dst: 0, Size: FixedTableFixedBodyBytes, Guard: tableFixedNoGuard, Op: tableFixedCopy,
}}, Count: 1}

// A FILE: form byte, seven reserved zeros, the LAYOUT HASH at 8, body at 16,
// then the layout behind its u32 length, then the records to the end of it.
func FixedTableFixedMeasure(count int64) int64 {
	return TableFixedHeaderBytes + 4 + int64(len(FixedTableFixedLayout)) + count*FixedTableFixedRecordBytes
}

func FixedTableFixedSave(values []FixedTable, buffer []byte) int64 {
	need := FixedTableFixedMeasure(int64(len(values)))
	if int64(len(buffer)) < need {
		return -1
	}
	clear(buffer[:TableFixedHeaderBytes])
	buffer[0] = TableFixedForm
	tableFixedPut64(buffer[TableFixedHashAt:], FixedTableFixedHash)
	tableFixedPut32(buffer[TableFixedHeaderBytes:], uint32(len(FixedTableFixedLayout)))
	copy(buffer[TableFixedHeaderBytes+4:], FixedTableFixedLayout)
	at := buffer[TableFixedHeaderBytes+4+len(FixedTableFixedLayout):]
	for k := range values {
		tableFixedPut64(at, FixedTableFixedHash)
		clear(at[8 : 8+FixedTableFixedBodyBytes])
		FixedTableFixedWriteBody(at[8:], &values[k])
		at = at[FixedTableFixedRecordBytes:]
	}
	return need
}

func FixedTableFixedLoad(values []FixedTable, data []byte, plan []TableFixedEntry, report *TableReport) int64 {
	if report == nil {
		var local TableReport
		report = &local
	}
	if len(data) < TableFixedHeaderBytes+4 {
		report.Malformed = true
		return -1
	}
	if data[0] != TableFixedForm {
		switch data[0] {
		case 1: // the VARIABLE form, and the only form this one is newer than
			return tableFixedRefuse(report, "previous_form")
		case 2: // the MESSAGE form: a form this build carries, through another surface
			return tableFixedRefuse(report, "message_form_as_file")
		}
		return tableFixedRefuse(report, "newer_form")
	}
	layoutBytes := tableFixedGet32(data[TableFixedHeaderBytes:])
	if int64(layoutBytes)+TableFixedHeaderBytes+4 > int64(len(data)) {
		return tableFixedRefuse(report, "layout_malformed")
	}
	layout := data[TableFixedHeaderBytes+4 : TableFixedHeaderBytes+4+layoutBytes]
	hash := tableFixedHashOf(layout)
	if tableFixedGet64(data[TableFixedHashAt:]) != hash {
		return tableFixedRefuse(report, "layout_malformed")
	}
	at := data[TableFixedHeaderBytes+4+layoutBytes:]
	rest := int64(len(data)) - TableFixedHeaderBytes - 4 - int64(layoutBytes)
	entries := FixedTableFixedPlan.Entries
	entryCount := FixedTableFixedPlan.Count
	recordBytes := int64(FixedTableFixedRecordBytes)
	identity := hash == FixedTableFixedHash
	if !identity {
		parsed, ok := tableFixedParseLayout(layout)
		if !ok {
			return tableFixedRefuse(report, "layout_malformed")
		}
		made := tableFixedCompile(parsed, FixedTableFixedLayout, FixedTableFixedDst, plan, report)
		if made < 0 {
			return tableFixedRefuse(report, "plan_too_large")
		}
		entries = plan
		entryCount = made
		recordBytes = 8 + int64(tableFixedEntryAt(parsed, 0).Size)
	}
	if recordBytes <= 8 || rest%recordBytes != 0 {
		report.Malformed = true
		return -1
	}
	n := rest / recordBytes
	if n > int64(len(values)) {
		return tableFixedRefuse(report, "batch_too_large")
	}
	var image [FixedTableFixedBodyBytes]byte
	holes := tableFixedHoles(entries, entryCount, FixedTableFixedBodyBytes)
	for k := int64(0); k < n; k++ {
		for i := range holes {
			h := holes[i]
			copy(image[h.Off:h.Off+h.Size], FixedTableFixedDefaults[h.Off:h.Off+h.Size])
		}
		if tableFixedGet64(at) != hash {
			return tableFixedRefuse(report, "no_layout")
		}
		tableFixedRun(entries, entryCount, at[8:], image[:], report)
		FixedTableFixedScatter(image[:], &values[k], report)
		at = at[recordBytes:]
	}
	return n
}

